insert into chart_templates
  (country, code, name, name_i18n, is_default, audience, statements,
   certification_status, legal_reference, source_key)
values
  ('ME', 'default', 'Kontni okvir za privredna društva i druga pravna lica', '{"en":"Chart of accounts for companies and other legal entities"}'::jsonb, true, 'companies', array['ME-FS-BS', 'ME-FS-IS']::text[], null, 'Pravilnik o kontnom okviru i sadržini računa u kontnom okviru za privredna društva i druga pravna lica ("Sl. list CG", br. 11/20, koji zamjenjuje Pravilnik iz 2011 — "Sl. list CG", br. 5/11, iste podjele na klase 0-9). Ovaj paket transkribuje klase 0 do 6 (stalna imovina, zalihe, kratkoročna potraživanja i gotovina, kapital, dugoročna rezervisanja i obaveze, rashodi, prihodi) i njihove najčešće korišćene grupe i konta prvog reda; klase 7 (otvaranje i zaključak računa), 8 (vanbilansna evidencija) i 9 (obračun troškova i učinaka) nijesu transkribovane jer ih socle ne zahtijeva — zatvaranje poslovne godine obavlja `close_fiscal_year()` preko uloga (`defaults.roles`), a vanbilansna evidencija i obračun troškova po mjestima troškova nijesu dio ovog izdanja. Uputstvo o primjeni Pravilnika izričito dozvoljava pravnim licima da uvedu podračune višeg reda uz zadržavanje brojčane oznake konta iz Kontnog okvira; na toj osnovi ovaj paket dodaje četvorocifrene podračune 2715/2717 (ulazni PDV po stopama od 15% i 7%, koje Kontni okvir iz 2011/2020 ne razlikuje jer je stopa od 15% uvedena tek 01.01.2025), 4711/4717 (odgovarajuće obaveze za PDV po izdatim fakturama) i 4698 (razlike po osnovu zaokruživanja, konto koji Kontni okvir ne imenuje posebno). Vidjeti README.md.', 'kontni-okvir')
on conflict (country, code) do update set
  name                 = excluded.name,
  name_i18n            = excluded.name_i18n,
  is_default           = excluded.is_default,
  audience             = excluded.audience,
  statements           = excluded.statements,
  certification_status = excluded.certification_status,
  legal_reference      = excluded.legal_reference,
  source_key           = excluded.source_key;

