insert into tax_templates
  (country, code, name, name_i18n, description, amount_type, amount, applies_to, treatment,
   valid_from, valid_to, legal_reference, vat_category, exemption_code, sequence,
   tax_kind, recoverable, conditions, jurisdiction, price_include, cash_basis,
   cash_basis_transition_account_code, source_key,
   applies_seller_territory, applies_buyer_territory, applies_supply_territory,
   applies_supply_vs_seller)
values
  ('ME', 'ME-P-15', 'PDV 15% — smještaj, hrana i piće u ugostiteljstvu, knjige i dr. (nabavka)', '{"en":"VAT 15% — accommodation, food and drink in hospitality, books etc. (purchase)"}'::jsonb, null, 'percent', 15, 'purchase', 'domestic', date '2025-01-01', null, 'Zakon o porezu na dodatu vrijednost, član 24a stav 2 i član 37 — pravo na odbitak ulaznog PDV obračunatog po sniženoj stopi od 15% (usluge smještaja, hrane i pića u ugostiteljstvu, knjige), pod uslovima člana 37.', null, null, 70, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'pdv-zakon', null, null, null, null),
  ('ME', 'ME-P-21', 'PDV 21% — opšta stopa (nabavka)', '{"en":"VAT 21% — standard rate (purchase)"}'::jsonb, null, 'percent', 21, 'purchase', 'domestic', date '2018-01-01', null, 'Zakon o porezu na dodatu vrijednost, član 24 (stopa) i član 37 (uslovi za odbijanje ulaznog PDV) — poreski obveznik može odbiti PDV koji je dužan da plati ili je platio prilikom nabavke proizvoda, odnosno usluga, ako ih koristi u svrhe ostvarivanja prihoda pri obavljanju oporezive djelatnosti.', null, null, 60, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'pdv-zakon', null, null, null, null),
  ('ME', 'ME-P-7', 'PDV 7% — osnovni proizvodi za ljudsku ishranu i dr. (nabavka)', '{"en":"VAT 7% — basic foodstuffs and other essentials (purchase)"}'::jsonb, null, 'percent', 7, 'purchase', 'domestic', date '2018-01-01', null, 'Zakon o porezu na dodatu vrijednost, član 24a stav 1 tačka 1 i član 37 — pravo na odbitak ulaznog PDV obračunatog po sniženoj stopi od 7% na osnovne proizvode za ljudsku ishranu.', null, null, 80, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'pdv-zakon', null, null, null, null),
  ('ME', 'ME-P-FOREIGN', 'PDV 21% — usluge inostranih lica, poreski dužnik primalac (nabavka)', '{"en":"VAT 21% — services from foreign persons, recipient is the tax debtor (purchase)"}'::jsonb, null, 'percent', 21, 'purchase', 'foreign_services_received', date '2018-01-01', null, 'Zakon o porezu na dodatu vrijednost, član 12 stav 1 tačka 2 — poreski dužnik PDV je poreski zastupnik, odnosno, kada ga poreski obveznik koji nema sjedište u Crnoj Gori ne imenuje, primalac proizvoda, odnosno usluga plaća PDV. Obrazac PR PDV-2, redni broj 21 ("PDV na usluge inostranih lica") — iznos se istovremeno iskazuje kao dio izlaznog PDV (obračunat na uslugu, redni broj 24) i kao dio ulaznog PDV (pretporez, redni broj 25), pod uslovom da poreski obveznik ima pravo na odbitak prema članu 37. Ovaj paket pretpostavlja opštu stopu od 21% za samooporezovanu uslugu; kad bi osnovna usluga, da je izvršio rezident, nosila sniženu stopu, treba provjeriti sa računovođom.', null, null, 90, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'pdv-zakon', null, null, null, null),
  ('ME', 'ME-S-15', 'PDV 15% — smještaj, hrana i piće u ugostiteljstvu, knjige i dr. (prodaja)', '{"en":"VAT 15% — accommodation, food and drink in hospitality, books etc. (sale)"}'::jsonb, null, 'percent', 15, 'sale', 'domestic', date '2025-01-01', null, 'Zakon o porezu na dodatu vrijednost, član 24a stav 2 — snižena stopa od 15% se, između ostalog, obračunava i plaća na usluge smještaja u ugostiteljskim objektima za smještaj (tačka 2), na usluge pripremanja i usluživanja hrane, pića i napitaka u ugostiteljskim objektima, osim alkoholnih pića, gaziranih i negaziranih pića sa dodatkom šećera i kafe (tačka 3), i na knjige, monografske i serijske publikacije (tačka 1). Izmjena je uvedena Zakonom o izmjenama i dopuni Zakona o porezu na dodatu vrijednost, "Sl. list CG", br. 094/24 od 30.09.2024, u primjeni od 01.01.2025 (prije toga usluge smještaja bile su oporezovane po stopi od 7%).', null, null, 20, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'pdv-zakon', null, null, null, null),
  ('ME', 'ME-S-21', 'PDV 21% — opšta stopa (prodaja)', '{"en":"VAT 21% — standard rate (sale)"}'::jsonb, null, 'percent', 21, 'sale', 'domestic', date '2018-01-01', null, 'Zakon o porezu na dodatu vrijednost, član 24 — PDV se obračunava i plaća po opštoj stopi od 21% od svakog prometa proizvoda, usluga i uvoza proizvoda, osim prometa za koji je propisana snižena ili nulta stopa.', null, null, 10, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'pdv-zakon', null, null, null, null),
  ('ME', 'ME-S-7', 'PDV 7% — osnovni proizvodi za ljudsku ishranu i dr. (prodaja)', '{"en":"VAT 7% — basic foodstuffs and other essentials (sale)"}'::jsonb, null, 'percent', 7, 'sale', 'domestic', date '2025-01-01', null, 'Zakon o porezu na dodatu vrijednost, član 24a stav 1 tačka 1 — snižena stopa od 7% se obračunava i plaća na promet osnovnih proizvoda za ljudsku ishranu (hljeb, brašno, mlijeko i mliječni proizvodi, hrana za odojčad, mast, ulje, meso, jaja i šećer). Rate carries the same 7% since the amendment of "Sl. list CG", br. 094/24 od 30.09.2024 (u primjeni od 01.01.2025), koja je samo dio proizvoda i usluga sa stope 7% prebacila na novu stopu od 15%.', null, null, 30, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'pdv-zakon', null, null, null, null),
  ('ME', 'ME-S-EXEMPT-LEASE', 'Oslobođeno PDV — dugoročni zakup stambenog prostora (prodaja)', '{"en":"Exempt from VAT — long-term residential lease (sale)"}'::jsonb, null, 'percent', 0, 'sale', 'exempt', date '2018-01-01', null, 'Zakon o porezu na dodatu vrijednost, član 27 stav 1 tačka 3 — plaćanja PDV su oslobođene usluge davanja u zakup ili podzakup kuća za stanovanje, stanova, odnosno stambenih prostora za stalno stanovanje duže od 60 dana, kao i zakup poljoprivrednog zemljišta ili šuma, koji su upisani u zemljišne knjige. Crna Gora je izvan zajedničkog sistema PDV Evropske unije (Direktiva 2006/112/EZ, član 5 stav 2, ne obavezuje kandidata za pristupanje), pa ovaj paket ne pripisuje kôd VATEX niti kategoriju BT-118/BT-151 ovoj tarifi — vidjeti docs/packs.md, odjeljak o zemljama van zajedničkog sistema PDV.', null, null, 50, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'pdv-zakon', null, null, null, null),
  ('ME', 'ME-S-EXPORT', 'PDV 0% — izvoz proizvoda (prodaja)', '{"en":"VAT 0% — export of goods (sale)"}'::jsonb, null, 'percent', 0, 'sale', 'export', date '2018-01-01', null, 'Zakon o porezu na dodatu vrijednost, član 25 stav 1 tačka 1 — PDV se plaća po stopi od 0% na proizvode koje iz Crne Gore izvozi prodavac, odnosno proizvode koje za njegov račun izvozi drugo lice.', null, null, 40, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'pdv-zakon', null, null, null, null)
on conflict (country, code) do update set
  name            = excluded.name,
  name_i18n       = excluded.name_i18n,
  description     = excluded.description,
  amount_type     = excluded.amount_type,
  amount          = excluded.amount,
  applies_to      = excluded.applies_to,
  treatment       = excluded.treatment,
  valid_from      = excluded.valid_from,
  valid_to        = excluded.valid_to,
  legal_reference = excluded.legal_reference,
  vat_category    = excluded.vat_category,
  exemption_code  = excluded.exemption_code,
  sequence        = excluded.sequence,
  tax_kind        = excluded.tax_kind,
  recoverable     = excluded.recoverable,
  conditions      = excluded.conditions,
  jurisdiction    = excluded.jurisdiction,
  price_include   = excluded.price_include,
  cash_basis      = excluded.cash_basis,
  cash_basis_transition_account_code = excluded.cash_basis_transition_account_code,
  source_key      = excluded.source_key,
  applies_seller_territory = excluded.applies_seller_territory,
  applies_buyer_territory  = excluded.applies_buyer_territory,
  applies_supply_territory = excluded.applies_supply_territory,
  applies_supply_vs_seller = excluded.applies_supply_vs_seller;

