insert into tax_report_templates
  (country, code, name, periods, period_default, valid_from, valid_to, legal_reference,
   is_periodic_return, deadline_rule, deadline_day, deadline_plus_days,
   deadline_reference, deadline_source_key, file_format)
values
  ('ME', 'ME-PR-PDV-2', 'Mjesečna prijava za obračun poreza na dodatu vrijednost — Obrazac PR PDV-2', array['month']::declaration_period[], 'month'::declaration_period, date '2025-01-01', null, 'Obrazac PR PDV-2, propisan od strane Uprave prihoda i carina. Zakon o porezu na dodatu vrijednost, član 33 stav 2 — poreski period je period od prvog do zadnjeg dana u mjesecu (kalendarski mjesec), jedina propisana dinamika. Ovaj paket transkribuje redne brojeve obrasca koje njegovi porezi dosežu: oporezivi promet i PDV po stopama od 21%, 15% i 7% (redni brojevi 10/16, 11/17, 12/18), promet po nultoj stopi (13) i oslobođeni promet (14), ulazni PDV na domaći promet (19) i PDV na usluge inostranih lica (21), te zbirne redne brojeve 24, 25, 28 i 29. Nijesu transkribovani: redni broj 9 (obilježje "bez transakcija", nije numerička vrijednost), 15 i 23 (promet/PDV prirodnog gasa, električne energije i energije za grijanje ili hlađenje za koji je izvršen prenos poreske obaveze — uska energetska šema van obima ovog izdanja), 20 (PDV plaćen na uvoz — socle ovog izdanja nema modul carinskog uvoza), 22 (paušalna nadoknada poljoprivredniku po stopi od 8% — posebna šema van obima), 26 i 27 (razdvajanje ulaznog PDV bez i sa pravom na odbitak — ovaj paket pretpostavlja puno pravo na odbitak i ne modeluje srazmjerni odbitak iz člana 38), i 30 (zahtjev za povraćaj PDV kredita, administrativno polje). Vidjeti README.md i docs/international.md, odjeljak «From Montenegro».', true,'day_of_month_after_period'::filing_deadline_rule, 15, null, 'Zakon o porezu na dodatu vrijednost, član 35 stav 2 — poreski obveznik prijavu za obračun PDV podnosi elektronskim putem nadležnom poreskom organu do 15. dana narednog mjeseca po isteku poreskog perioda; član 36 stav 1 — poreska obaveza za poreski period dospijeva za plaćanje istog dana, 15. dana u mjesecu po isteku poreskog perioda. Ovo polje modeluje samo rok za podnošenje prijave; socle ne razlikuje rok podnošenja od roka plaćanja, koji se ovdje poklapaju.', 'pdv-zakon', null)
on conflict (country, code) do update set
  name                = excluded.name,
  periods             = excluded.periods,
  period_default      = excluded.period_default,
  valid_from          = excluded.valid_from,
  valid_to            = excluded.valid_to,
  legal_reference     = excluded.legal_reference,
  is_periodic_return  = excluded.is_periodic_return,
  deadline_rule       = excluded.deadline_rule,
  deadline_day        = excluded.deadline_day,
  deadline_plus_days  = excluded.deadline_plus_days,
  deadline_reference  = excluded.deadline_reference,
  deadline_source_key = excluded.deadline_source_key,
  file_format         = excluded.file_format;

insert into tax_report_box_templates
  (country, report_code, box, kind, name, name_i18n, sequence, print_sequence,
   plus_boxes, minus_boxes, rate, rate_of_box, floor_zero, hidden, xml_element,
   legal_reference, source_key)
values
  ('ME', 'ME-PR-PDV-2', '10', 'base', 'Oporezivi promet (isporuke) po stopi od 21%', '{"en":"Taxable supplies at the rate of 21%"}'::jsonb, 10, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Obrazac PR PDV-2, redni broj 10.', 'pdv-prijava-obrazac'),
  ('ME', 'ME-PR-PDV-2', '11', 'base', 'Oporezivi promet (isporuke) po stopi od 15%', '{"en":"Taxable supplies at the rate of 15%"}'::jsonb, 20, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Obrazac PR PDV-2, redni broj 11.', 'pdv-prijava-obrazac'),
  ('ME', 'ME-PR-PDV-2', '12', 'base', 'Oporezivi promet (isporuke) po stopi od 7%', '{"en":"Taxable supplies at the rate of 7%"}'::jsonb, 30, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Obrazac PR PDV-2, redni broj 12.', 'pdv-prijava-obrazac'),
  ('ME', 'ME-PR-PDV-2', '13', 'base', 'Oporezivi promet (isporuke) po stopi od 0%', '{"en":"Taxable supplies at the rate of 0%"}'::jsonb, 40, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Obrazac PR PDV-2, redni broj 13; Zakon o porezu na dodatu vrijednost, član 25.', 'pdv-prijava-obrazac'),
  ('ME', 'ME-PR-PDV-2', '14', 'base', 'Oslobođeni promet — isporuke', '{"en":"Exempt supplies"}'::jsonb, 50, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Obrazac PR PDV-2, redni broj 14; Zakon o porezu na dodatu vrijednost, čl. 26 i 27.', 'pdv-prijava-obrazac'),
  ('ME', 'ME-PR-PDV-2', '16', 'tax', 'PDV na domaći promet proizvoda i usluga po stopi od 21%', '{"en":"VAT on domestic supplies at the rate of 21%"}'::jsonb, 60, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Obrazac PR PDV-2, redni broj 16.', 'pdv-prijava-obrazac'),
  ('ME', 'ME-PR-PDV-2', '17', 'tax', 'PDV na domaći promet proizvoda i usluga po stopi od 15%', '{"en":"VAT on domestic supplies at the rate of 15%"}'::jsonb, 70, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Obrazac PR PDV-2, redni broj 17.', 'pdv-prijava-obrazac'),
  ('ME', 'ME-PR-PDV-2', '18', 'tax', 'PDV na domaći promet proizvoda i usluga po stopi od 7%', '{"en":"VAT on domestic supplies at the rate of 7%"}'::jsonb, 80, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Obrazac PR PDV-2, redni broj 18.', 'pdv-prijava-obrazac'),
  ('ME', 'ME-PR-PDV-2', '19', 'tax', 'Ulazni PDV na domaći promet proizvoda i usluga', '{"en":"Input VAT on domestic supplies"}'::jsonb, 90, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Obrazac PR PDV-2, redni broj 19.', 'pdv-prijava-obrazac'),
  ('ME', 'ME-PR-PDV-2', '21', 'tax', 'PDV na usluge inostranih lica', '{"en":"VAT on services from foreign persons"}'::jsonb, 100, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Obrazac PR PDV-2, redni broj 21; Zakon o porezu na dodatu vrijednost, član 12 stav 1 tačka 2 — istovremeno dio izlaznog PDV (redni broj 24) i ulaznog PDV (redni broj 25).', 'pdv-prijava-obrazac'),
  ('ME', 'ME-PR-PDV-2', '24', 'total', 'Ukupan izlazni PDV na isporuke', '{"en":"Total output VAT on supplies"}'::jsonb, 110, null, array['16', '17', '18', '21']::text[], '{}'::text[], null, null, false, false, null, 'Obrazac PR PDV-2, redni broj 24 — zbir rednih brojeva 16+17+18+21.', 'pdv-prijava-obrazac'),
  ('ME', 'ME-PR-PDV-2', '25', 'total', 'Ukupan ulazni PDV — pretporez', '{"en":"Total input VAT (deductible)"}'::jsonb, 120, null, array['19', '21']::text[], '{}'::text[], null, null, false, false, null, 'Obrazac PR PDV-2, redni broj 25 — zbir rednih brojeva 19+20+21+22; ovaj paket ne transkribuje redne brojeve 20 (uvoz) i 22 (paušalna nadoknada poljoprivredniku), pa ovdje zbraja samo 19+21. Vidjeti napomenu na vrhu ovog fajla.', 'pdv-prijava-obrazac'),
  ('ME', 'ME-PR-PDV-2', '28', 'total', 'Dospjeli PDV za uplatu', '{"en":"VAT due for payment"}'::jsonb, 130, null, array['24']::text[], array['25']::text[], null, null, true, false, null, 'Obrazac PR PDV-2, redni broj 28 — razlika rednih brojeva 24-27; ovaj paket ne transkribuje redni broj 26 (ulazni PDV bez prava na odbitak) niti 27 (25 minus 26) i pretpostavlja puno pravo na odbitak, pa ovdje oduzima direktno redni broj 25.', 'pdv-prijava-obrazac'),
  ('ME', 'ME-PR-PDV-2', '29', 'total', 'PDV kredit', '{"en":"VAT credit"}'::jsonb, 140, null, array['25']::text[], array['24']::text[], null, null, true, false, null, 'Obrazac PR PDV-2, redni broj 29 — razlika rednih brojeva 27-24, ovdje 25-24 iz istog razloga kao redni broj 28.', 'pdv-prijava-obrazac')
on conflict (country, report_code, box, kind) do update set
  name            = excluded.name,
