insert into statement_templates
  (code, country, chart_code, name, kind, framework, valid_from, valid_to, legal_reference,
   source_key)
values
  ('ME-FS-BS', 'ME', 'default', 'Iskaz o finansijskoj poziciji /Bilans stanja/', 'balance_sheet', 'MSFI / Zakon o računovodstvu', date '2018-01-01', null, 'Zakon o računovodstvu ("Sl. list CG", br. 052/16), član 4, i Pravilnik o sadržini i formi obrazaca finansijskih iskaza za privredna društva i druga pravna lica, usklađen sa Direktivom 2013/34/EU — obrazac "Iskaz o finansijskoj poziciji /Bilans stanja/" nosi redne brojeve (AOP) od 001 do 144. Ovaj paket transkribuje jedanaest zbirnih redova na nivou klase/grupe konta Kontnog okvira umjesto svakog od preko sto pojedinačnih redova obrasca — svaki konto ovog paketa dostiže tačno jedan od njih. Kompletnu podjelu po pojedinačnim rednim brojevima obrasca vidjeti u README.md.', 'fin-iskazi-obrazac'),
  ('ME-FS-IS', 'ME', 'default', 'Iskaz o ukupnom rezultatu /Bilans uspjeha/', 'income_statement', 'MSFI / Zakon o računovodstvu', date '2018-01-01', null, 'Zakon o računovodstvu ("Sl. list CG", br. 052/16), član 4, i Pravilnik o sadržini i formi obrazaca finansijskih iskaza za privredna društva i druga pravna lica — obrazac "Iskaz o ukupnom rezultatu /Bilans uspjeha/" nosi redne brojeve (AOP) od 201 do 265. Ovaj paket transkribuje trinaest zbirnih redova na nivou klase/grupe konta Kontnog okvira umjesto svakog pojedinačnog reda obrasca (koji dalje razlaže prihode i rashode po povezanim/nepovezanim licima); ne transkribuje redove 249-265 (bruto rezultat drugih stavki rezultata povezanih sa kapitalom — nerealizovani dobici/gubici po osnovu revalorizacije, hedžinga i sl.), koje nijedan konto ovog paketa ne dostiže. Vidjeti README.md.', 'fin-iskazi-obrazac')
on conflict (code) do update set
  country         = excluded.country,
  chart_code      = excluded.chart_code,
  name            = excluded.name,
  kind            = excluded.kind,
  framework       = excluded.framework,
  valid_from      = excluded.valid_from,
  valid_to        = excluded.valid_to,
  legal_reference = excluded.legal_reference,
  source_key      = excluded.source_key;

